; The Mirewood, the rangers' wood east of the old road, at twilight. In from the road on the west,
; where it's still the same bright wood, and along the rangers' trail through the clearing where
; the Gloomfangs are, past Sera's camp off to the south, over the bridge where the wood turns, and
; up through the rot to the old quarry's mouth in the rock to the north-east. The stream comes out
; of the rock beside the mouth, black with tar, and down through the wood to the south. The trees
; are props standing in the undergrowth, so their crowns overlap and overhang the verges, the same
; as the road's; past the stream they're the black-veined ones, and the undergrowth's rotten too.

[map]
id = mirewood
name = The Mirewood
world = 900 330
tileset = mirewood
size = 50 40
dark = yes
ambient = 0.62          ; twilight: the dark is only so the camp's fire and the sun at the west edge count
tint = 196 188 226      ; a cool grey-violet over all of it
music = Exploring

[legend]
, = grass
- = grass-wilt
' = grass-rot
l = leaves
k = leaves-blackvein
g = gloom-moss
: = trail
~ = tar-stream
U = undergrowth
Y = undergrowth-rot
^ = cliff-top
F = cliff-face
B = cliff-base
v = tuft
* = flowers
f = fern
o = pebbles
r = roots
% = litter
x = veins
d = tuft-dead
m = toadstools
s = tar-spatter
b = brambles
t = tar-slick

