; kind id x y, in tiles, then any settings. Exits and triggers are rectangles from their top left tile.
[objects]
spawn start 1.5 18.5 facing=right
spawn road 1.5 18.5 facing=right
spawn quarry 41 8 facing=down
spawn camp 12 31.5 facing=right
exit road 0 14 h=8 to=road at=mirewood
exit quarry 40 4 w=3 to=mirewood-quarry at=mouth

; The light. The wood's twilight is the map's tint and its ambient; where the trees open up at
; the west edge the sun still gets through, onto the trail, the glade and the clearing.
light sun-west 4 18.5 reach=8 strength=0.5
light sun-glade 5.5 10.5 reach=5 strength=0.45
light sun-clearing 14 18.5 reach=7 strength=0.35

; The west edge, still the bright wood the road comes through: the rangers' sign, flowers, and a
; glade off to the north with a chest somebody hid under the ferns.
sign west-sign 3 16.6 look=ranger-sign name="Rangers' sign" text="The Mirewood. Rangers' Lodge land: keep to the trail."
prop flowers-white 6.2 16.3
prop flowers-mixed 10.4 21.6
prop flowers-pink 2.6 21.4
prop bush-flowers 7.8 21.5
prop flowers-mixed 4.2 11.8
prop fern 2.8 9.6
chest glade 5 9.4 gold=15

; The clearing where the Gloomfangs are, a few tiles in. A1-C2-01 starts as you walk in, from the
; trail or the grass either side of it. Sera's at the tree line on its north side, in the shadow
; under the trees, until she's with you. The first of the black veins are in the clearing's grass,
; and what's left of the wolves' last meal.
trigger a1-c2-01 9 15 h=9 talk=a1-c2-01 when=a1-c1-02 unless=a1-c2-01
npc wolf-1 13 16.4 creature=gloomfang facing=left unless=gloomfangs-beaten
npc wolf-2 15.6 18.2 creature=gloomfang facing=left unless=gloomfangs-beaten
npc wolf-3 13.4 20.6 creature=gloomfang facing=left unless=gloomfangs-beaten
npc wolf-4 16.8 21.2 creature=gloomfang facing=left unless=gloomfangs-beaten
npc sera 14.5 13.8 cast=sera facing=down unless=sera-recruited
prop bones 18.2 21.6
prop log 18.6 15.2
prop rocks-mossy 10.6 15.2

; Sera's camp, off the clearing to the south: her fire, a log to sit on, the bedrolls, her crate,
; and the waypoint stone the rangers keep. The night after the quarry plays here, and Travel puts
; you at the camp spawn by the fire.
prop campfire 13.5 30
prop log 13.6 28.4
prop bedroll 10.8 31.4
prop bedroll 16.4 31.2
prop crate 17.4 29.2
prop barrel 17.6 30.4
prop grass-tall 9.4 28.6
waypoint stone 9.5 30
scene a1-c2-03 13 31 talk=a1-c2-03 when=a1-c2-02 unless=a1-c2-03

; The bridge the rangers built over the stream, which is where the wood turns, with their sign
; warning you off the water, and the tar starting to show along the banks.
prop ranger-bridge 29.5 19.75
sign bridge-sign 27 16.8 look=ranger-sign name="Rangers' sign" text="Old quarry, east. Closed by order of the Lodge. Don't drink from the stream."
prop gloom-mushroom-small 32.4 21.4
prop tar-pool 34.2 22.4

; The woodcutters' yard by the trail north of the bridge, left the way they left it: the oak they
; were felling with the axe still in it, the logs, their crate and their pay.
prop woodcutter-stump 43.4 12.4
prop log 45.6 14.8
prop log 42.2 15.6
prop crate 40.4 11.2
chest woodcutters 46.2 12 gold=30

; The tar glade, south off the yard: tar welling up in pools, the gloom mushrooms that grow round
; them, the bones of a deer that drank there, and a chest past the pools.
prop tar-pool 43.6 22.2
prop tar-pool 46.4 24.8
prop gloom-mushroom 41.6 20.4
prop gloom-mushroom 47.6 21.2
prop gloom-mushroom-small 44.8 26.2
prop gloom-mushroom-small 40.8 23.6
prop bones 42.4 25
light glow-glade 44.5 22.5 reach=3 strength=0.3
chest tar-glade 47.2 22.6 gold=45

; The quarry's mouth, cut into the rock to the north-east, the trail running up into it. The stream
; comes out of the foot of the rock beside it, black where it starts. The rangers have a sign up
; here too.
prop quarry-mouth 41 5.5
sign quarry-sign 38.4 8.6 look=ranger-sign name="Rangers' sign" text="The Old Quarry. Nothing comes out of it right any more."
prop gloom-mushroom 36.8 7.4
prop tar-pool 44.6 8.2

; What the two of you say as you go: coming in, at the first veins, at the rangers' sign by the
; bridge, at the tar past it, and coming up to the quarry's mouth.
trigger bark-mirewood-edge 2 15 h=7 bark=mirewood-edge
trigger bark-mirewood-veins 20 14 h=8 bark=mirewood-veins
trigger bark-mirewood-ranger-sign 25 15 h=7 bark=mirewood-ranger-sign
trigger bark-mirewood-tar 34 14 h=9 bark=mirewood-tar
trigger bark-mirewood-quarry-mouth 37 10 w=7 bark=mirewood-quarry-mouth

